 for(let yy=Math.max(0,Math.round(y)-3);yy<Math.min(240,Math.round(y)+4);yy++)for(let xx=Math.max(0,Math.round(x)-3);xx<Math.min(320,Math.round(x)+4);xx++){const i=(yy*320+xx)*4,[h,s,v]=hsv(d[i],d[i+1],d[i+2]);if(s>.3&&v>.12){sx+=Math.cos(h*Math.PI/180);sy+=Math.sin(h*Math.PI/180);n++}}
 if(n<10){$('status').textContent='Tap the colored center of the ball, away from glare.';return}
 if(anchors.length&&x<anchors[anchors.length-1].x+18){$('status').textContent='Tap a different ball, going from LEFT to RIGHT in the preview.';return}
 const h=(Math.atan2(sy,sx)*180/Math.PI+360)%360,a={x,y,h};const found=LittleLungsVision.findBall(d,320,240,a,true);
 if(!found){$('status').textContent='Ball color is unclear. Improve the light and tap its center again.';return}
 a.x=found.x;a.y=found.y;a.prevX=found.x;a.prevY=found.y;anchors.push(a);
